  B.box('metal', x + Math.sin(rot || 0) * 0.5, 4.75, z + Math.cos(rot || 0) * 0.5, 0.25, 0.08, 1.1, 0x556070, { rot: rot || 0 });
  WORLD.lamps.push(new THREE.Vector3(x + Math.sin(rot || 0) * 0.95, 4.6, z + Math.cos(rot || 0) * 0.95));
